#!/usr/bin/env node
/**
 * The media worker deploys from workers/media-worker only (render.yaml dockerContext), so it cannot import
 * from src/. The render planner therefore has ONE source of truth in src/features/fresh-studio/video-studio
 * and this script generates the worker's copy by stripping types.
 *
 *   node scripts/sync-studio-worker.mjs          write the generated files
 *   node scripts/sync-studio-worker.mjs --check  exit 1 if they are out of date (used by tests/CI)
 */
import fs from "node:fs";
import { stripTypeScriptTypes } from "node:module";

const SRC = new URL("../src/features/fresh-studio/video-studio/", import.meta.url);
const OUT = new URL("../workers/media-worker/vendor/", import.meta.url);
export const SHARED = ["timeline", "film", "captions", "renderPlan"];

const HEADER = "// GENERATED by scripts/sync-studio-worker.mjs from src/features/fresh-studio/video-studio. Do not edit.\n";

export function generate() {
  const files = new Map();
  for (const name of SHARED) {
    const source = fs.readFileSync(new URL(`${name}.ts`, SRC), "utf8");
    const js = stripTypeScriptTypes(source, { mode: "strip" }).replace(/(from\s+["']\.\/[A-Za-z]+)\.ts(["'])/g, "$1.mjs$2");
    if (/\.ts["']/.test(js)) throw new Error(`${name}.ts still imports a .ts file after conversion`);
    files.set(`${name}.mjs`, HEADER + js);
  }
  return files;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const check = process.argv.includes("--check");
  const files = generate();
  let stale = 0;
  if (!check) fs.mkdirSync(OUT, { recursive: true });
  for (const [name, content] of files) {
    const target = new URL(name, OUT);
    const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : null;
    if (current === content) continue;
    stale += 1;
    if (check) console.error(`Out of date: workers/media-worker/vendor/${name}`);
    else fs.writeFileSync(target, content);
  }
  if (check && stale) { console.error("Run: node scripts/sync-studio-worker.mjs"); process.exit(1); }
  console.log(check ? "Worker planner copy is up to date." : `Wrote ${files.size} files to workers/media-worker/vendor/.`);
}
